use std::mem;

struct MyStruct {
    // Your structure fields here...
}

impl Drop for MyStruct {
    fn drop(&mut self) {
        println!("Dropping");
    }
}

fn main() {
    let my_struct = MyStruct {};

    // The program will now enter into the drop function automatically.
    // At this point, my_struct has been dropped, and the println! macro inside the drop method will execute.
